create table public.projects (id uuid primary key default gen_random_uuid(), competency_id uuid not null references public.competencies(id) on delete restrict, title text not null, brief text not null, configuration jsonb, status text not null default 'draft', created_by uuid not null references public.profiles(id) on delete restrict, created_at timestamptz not null default now(), updated_at timestamptz not null default now());;
